import { FollowButton, Card } from "march/ui"

// kulübe katıl: kendi metinleri ve yeşil renk; koyu kartta
export function ClubJoin() {
  let $state = "follow"
  return <Card m:theme="night">
    <strong>HADİ Koşu Kulübü</strong>
    <FollowButton state={$state as "follow"} onChange={(s: string) => $state = s} name="HADİ Koşu Kulübü"
      labels={{ follow: "Katıl", following: "Üyesin" }} m:color="brand-green" />
  </Card>
}

import { FollowButton, Avatar } from "march/ui"

// önerilen hesaplar: gizli hesapta istek gönderilir; takip sayısı altta
const people = [{ name: "Fotoğraf Atölyesi", private: false }, { name: "Kitap Kulübü", private: true }, { name: "Masa Oyunları", private: false }]

export function SuggestedList() {
  let $states: Record<string, string> = {}
  const count = () => Object.values($states).filter((s) => s !== "follow").length
  return <div sx={{ flex: "col", gap: 2 }}>
    {people.map((p) => <div sx={{ flex: ["row", "center"], gap: 2 }}>
      <Avatar name={p.name} size="sm" /><span sx={{ flex: "grow" }}>{p.name}</span>
      <FollowButton size="sm" name={p.name} private={p.private} state={($states[p.name] ?? "follow") as "follow"}
        onChange={(s: string) => $states = { ...$states, [p.name]: s }} />
    </div>)}
    <span sx={{ text: "sm", color: "muted" }}>{count()} hesap</span>
  </div>
}

import { FollowButton } from "march/ui"

// FollowButton'ın özellikleri: state, onChange, private, name, size, block, labels, ariaLabel, icon (işlev ya da false),
// burst, morph, class
export function FollowButtonLab() {
  let $state = "follow"
  return <div sx={{ flex: "col", gap: 2 }}>
    <FollowButton class="lab-follow" state={$state as "follow"} onChange={(s: string) => $state = s} name="Elif" size="md" block
      ariaLabel={(st: string, n: string | undefined) => `${n}: ${st}`} burst={false} morph={false} />
    <FollowButton class="lab-private" state="follow" onChange={() => {}} private icon={false} labels={{ follow: "İstek gönder" }} />
    <span class="lab-state">{$state}</span>
  </div>
}

import { test, expect, renderTest } from "march/testing"
import { FollowButtonLab } from "./FollowButtonLab.tsx"

// FollowButtonLab'in testleri: kaydedince Testler sekmesinde çalışır
test("basınca following olur, ariaLabel adı yazar", async () => {
  const s = renderTest(() => <FollowButtonLab />)
  expect(s.get(".lab-follow")?.getAttribute("aria-label")).toBe("Elif: follow")
  await s.click(s.get(".lab-follow")!)
  expect(s.get(".lab-state")?.textContent).toBe("following")
})

test("labels kendi metnini yazar", () => {
  const s = renderTest(() => <FollowButtonLab />)
  expect(s.get(".lab-private")?.textContent).toContain("İstek gönder")
})
